pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val, uint256 other) internal {
        vm.assume(other != val);
        try c.SetMinSum(val) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 stored;
        try c.MinSum() returns (uint256 __r) { stored = __r; } catch { return; }
        bool reverted = false;
        try c.SetMinSum(other) { } catch { reverted = true; }
        assertTrue(stored == val && reverted);
    }

    function testFuzz_run(uint256 val, uint256 other) public {
        _run(val, other);
    }

    receive() external payable {}
}
